#include <cmath>
#include <string>
#define main original_main
#include "../gd-cuda/main.cu"
#undef main
#include "../gd-cuda/utils.cpp"
static void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
static std::vector<double> oracle(const std::vector<int>&rows,const std::vector<int>&cols,const std::vector<float>&values,const std::vector<int>&labels){std::vector<double>x(512,0),grad(512);double obj=0,l2=0;int correct=0;for(int k=0;k<32;++k){std::fill(grad.begin(),grad.end(),0);obj=0;l2=0;correct=0;for(double v:x)l2+=v*v;for(int i=0;i<257;++i){double xp=0;for(int j=rows[i];j<rows[i+1];++j)xp+=double(values[j])*x[cols[j]];int y=labels[i];obj+=log1p(exp(-xp*y));correct+=((xp>=0)?1:-1)==y;double factor=-double(y)/(1+exp(y*xp));for(int j=rows[i];j<rows[i+1];++j)grad[cols[j]]+=factor*values[j];}for(int i=0;i<512;++i)x[i]-=double(.4f)*(grad[i]/257+double(.01f)*x[i]);}x.insert(x.end(),grad.begin(),grad.end());x.push_back(obj);x.push_back(l2);x.push_back(correct);return x;}
int main(){std::vector<int>rows{0},cols,labels;std::vector<float>values;for(int i=0;i<257;++i){int y=i%2?-1:1;labels.push_back(y);for(int c:{0,1+(37*i)%511,1+(37*i+13)%511,1+(37*i+211)%511})cols.push_back(c);for(float v:{.5f*y,-.5f,.5f,.5f})values.push_back(v);rows.push_back(cols.size());}std::vector<float>prefix;for(int v:rows)prefix.push_back(v);for(int v:cols)prefix.push_back(v);prefix.insert(prefix.end(),values.begin(),values.end());for(int v:labels)prefix.push_back(v);prefix.push_back(.01f);prefix.push_back(.4f);prefix.push_back(32);prefix.insert(prefix.end(),512,0);auto expected=oracle(rows,cols,values,labels);float*x,*g,*v,*obj,*l2;int*r,*c,*y,*correct;ck(cudaMalloc(&x,512*4));ck(cudaMalloc(&g,512*4));ck(cudaMalloc(&obj,4));ck(cudaMalloc(&l2,4));ck(cudaMalloc(&correct,4));ck(cudaMalloc(&r,rows.size()*4));ck(cudaMalloc(&c,cols.size()*4));ck(cudaMalloc(&v,values.size()*4));ck(cudaMalloc(&y,labels.size()*4));ck(cudaMemcpy(r,rows.data(),rows.size()*4,cudaMemcpyHostToDevice));ck(cudaMemcpy(c,cols.data(),cols.size()*4,cudaMemcpyHostToDevice));ck(cudaMemcpy(v,values.data(),values.size()*4,cudaMemcpyHostToDevice));ck(cudaMemcpy(y,labels.data(),labels.size()*4,cudaMemcpyHostToDevice));auto train=[&](){ck(cudaMemset(x,0,512*4));ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int k=0;k<32;++k){ck(cudaMemset(obj,0,4));ck(cudaMemset(l2,0,4));ck(cudaMemset(correct,0,4));ck(cudaMemset(g,0,512*4));compute<<<2,256>>>(x,g,r,c,v,y,obj,correct,257);update<<<2,256>>>(x,g,l2,257,512,.01f,.4f);}ck(cudaDeviceSynchronize());return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();};train();for(int tr=1;tr<=5;++tr){double elapsed=train();std::vector<float>got(1027);ck(cudaMemcpy(got.data(),x,512*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+512,g,512*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+1024,obj,4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+1025,l2,4,cudaMemcpyDeviceToHost));int hc;ck(cudaMemcpy(&hc,correct,4,cudaMemcpyDeviceToHost));got[1026]=hc;double err=0;bool ok=true;for(int i=0;i<1027;++i){double e=std::abs(double(got[i])-expected[i]);err=std::max(err,e);ok&=std::isfinite(got[i])&&e<=1e-4+1e-3*std::abs(expected[i]);}std::vector<float>out=prefix;out.insert(out.end(),got.begin(),got.end());std::string path="trial_"+std::to_string(tr)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":4113,\"max_abs_error\":%.17g,\"timing_region\":\"32_training_iterations_memsets_compute_update_sync\",\"jit_excluded\":true,\"internal_repeats\":32,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":4113,\"byte_order\":\"little\"}}\n",tr,elapsed,ok?"true":"false",err,path.c_str());if(!ok)return 3;}for(void*ptr:{(void*)x,(void*)g,(void*)obj,(void*)l2,(void*)correct,(void*)r,(void*)c,(void*)v,(void*)y})cudaFree(ptr);return 0;}
